SELECT id, observed_at, UNIX_TIMESTAMP(observed_at) AS obs_epoch, price, source, delivery_status, outcome_reason, created_at FROM crypto_ai.market_price_event WHERE symbol='EGLDUSDT' AND observed_at BETWEEN '2026-10-11 22:43:20' AND '2026-10-11 22:43:40' ORDER BY observed_at LIMIT 100;
SELECT open_time, close_time, open_price, high_price, low_price, close_price, volume, number_of_trades, closed, ingestion_source FROM crypto_ai.candle WHERE symbol='EGLDUSDT' AND interval_code='1m' AND open_time BETWEEN '2026-10-11 22:37:00' AND '2026-10-11 22:45:00' ORDER BY open_time LIMIT 20;
SELECT id, entry_price, exit_price, realized_pnl, close_reason, signal_id, opened_at, closed_at FROM crypto_ai.paper_position WHERE symbol='EGLDUSDT' AND closed_at BETWEEN '2026-10-11 22:00:00' AND '2026-10-11 22:41:00' ORDER BY closed_at LIMIT 5;